import { expect } from '@playwright/test';
import AxeBuilder from '@axe-core/playwright';

/**
 * Runs an axe scan for WCAG 2.0/2.1/2.2 A & AA against the current page state.
 */
export async function expectNoA11yViolations(page, context = {}) {
  const results = await new AxeBuilder({ page })
    .withTags(['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa', 'wcag22aa'])
    .analyze();
  expect(
    results.violations,
    `axe violations: ${results.violations
      .map((v) => `${v.id} (${v.impact}): ${v.nodes.map((n) => n.target).join(', ')}`)
      .join('\n')}`,
  ).toEqual([]);
}

/** Sizes offered on the page; sold-out sizes must not be selectable. */
export const SIZES = ['US 7', 'US 8', 'US 9', 'US 10', 'US 11', 'US 12'];
export const SOLD_OUT_SIZES = ['US 9', 'US 11'];

export default function App() {
  // Red phase: intentionally empty. Features are driven by the tests in tests/.
  return null;
}

import React from 'react';
import { createRoot } from 'react-dom/client';
import App from './App.jsx';

createRoot(document.getElementById('root')).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>,
);

import { test, expect } from '@playwright/test';
import { expectNoA11yViolations } from './helpers.js';

// Requirement: Store — the shopper sees the store name and how many items are
// in their cart.
// Requirement: Menu — the shopper can go to the store's main sections, such as
// men, women and kids, from the top of the page.

test.describe('Store header', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('shows the store name in the banner landmark', async ({ page }) => {
    const banner = page.getByRole('banner');
    await expect(banner).toBeVisible();
    await expect(banner).toContainText('Stride');
  });

  test('shows the cart with an item count', async ({ page }) => {
    const cart = page.getByRole('link', { name: /cart/i });
    await expect(cart).toBeVisible();
    // The shopper can see how many items are in the cart.
    await expect(cart).toContainText(/\d+/);
    await expect(cart).toHaveAttribute('href', /.+/);
  });

  test('main navigation links to men, women and kids sections', async ({
    page,
  }) => {
    const nav = page.getByRole('navigation', { name: /main/i });
    await expect(nav).toBeVisible();
    for (const section of ['Men', 'Women', 'Kids']) {
      const link = nav.getByRole('link', { name: section, exact: true });
      await expect(link).toBeVisible();
      await expect(link).toHaveAttribute('href', /.+/);
    }
  });

  test('header is reachable and operable by keyboard', async ({ page }) => {
    await page.keyboard.press('Tab');
    // First focusable element is inside the banner (skip link or store name).
    await expect(page.locator(':focus')).toBeVisible();
  });

  test('header has no WCAG 2.2 AA violations', async ({ page }) => {
    // Scan a fully rendered page, not an empty shell.
    await expect(page.getByRole('banner')).toBeVisible();
    await expectNoA11yViolations(page);
  });
});

import { test, expect } from '@playwright/test';

// Requirement: Price — the shopper sees the price and can point at a small "i"
// next to it to learn that it includes taxes.

test.describe('Price', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('shows the price of the shoe', async ({ page }) => {
    await expect(
      page.getByRole('heading', { name: 'Trail Runner 2', level: 1 }),
    ).toBeVisible();
    await expect(page.getByText(/\$\s?120/)).toBeVisible();
  });

  test('has an info button next to the price with an accessible name', async ({
    page,
  }) => {
    const info = page.getByRole('button', { name: /price information/i });
    await expect(info).toBeVisible();
  });

  test('pointing at the info reveals a tooltip saying taxes are included', async ({
    page,
  }) => {
    const info = page.getByRole('button', { name: /price information/i });
    await info.hover();
    const tooltip = page.getByRole('tooltip');
    await expect(tooltip).toBeVisible();
    await expect(tooltip).toContainText(/tax(es)?/i);
  });

  test('focusing the info button also reveals the tooltip (keyboard access)', async ({
    page,
  }) => {
    const info = page.getByRole('button', { name: /price information/i });
    await info.focus();
    const tooltip = page.getByRole('tooltip');
    await expect(tooltip).toBeVisible();
    // APG tooltip: the trigger references the tooltip content.
    const describedBy = await info.getAttribute('aria-describedby');
    expect(describedBy).toBeTruthy();
    await expect(page.locator(`#${describedBy}`)).toContainText(/tax(es)?/i);
  });

  test('Escape dismisses the tooltip', async ({ page }) => {
    const info = page.getByRole('button', { name: /price information/i });
    await info.focus();
    await expect(page.getByRole('tooltip')).toBeVisible();
    await page.keyboard.press('Escape');
    await expect(page.getByRole('tooltip')).toBeHidden();
  });
});

import { test, expect } from '@playwright/test';

// Requirement: Photos — the shopper sees one photo of the shoe at a time and
// moves to the next or previous one, going back to the first after the last.

const PHOTO_COUNT = 3;

test.describe('Photo carousel', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  function carousel(page) {
    return page.getByRole('region', { name: /product photos/i });
  }

  function currentPhoto(page) {
    return carousel(page).getByRole('img', { name: /trail runner 2/i });
  }

  test('shows exactly one photo of the shoe at a time', async ({ page }) => {
    await expect(carousel(page)).toBeVisible();
    await expect(currentPhoto(page)).toHaveCount(1);
    await expect(currentPhoto(page)).toBeVisible();
  });

  test('indicates which photo is shown out of the total', async ({ page }) => {
    await expect(carousel(page)).toContainText(`1 of ${PHOTO_COUNT}`);
  });

  test('next button moves to the next photo', async ({ page }) => {
    await carousel(page)
      .getByRole('button', { name: /next/i })
      .click();
    await expect(carousel(page)).toContainText(`2 of ${PHOTO_COUNT}`);
  });

  test('previous button moves to the previous photo', async ({ page }) => {
    await carousel(page)
      .getByRole('button', { name: /next/i })
      .click();
    await carousel(page)
      .getByRole('button', { name: /previous/i })
      .click();
    await expect(carousel(page)).toContainText(`1 of ${PHOTO_COUNT}`);
  });

  test('wraps back to the first photo after the last', async ({ page }) => {
    for (let i = 0; i < PHOTO_COUNT; i++) {
      await carousel(page)
        .getByRole('button', { name: /next/i })
        .click();
    }
    await expect(carousel(page)).toContainText(`1 of ${PHOTO_COUNT}`);
  });

  test('wraps to the last photo when going previous from the first', async ({
    page,
  }) => {
    await carousel(page)
      .getByRole('button', { name: /previous/i })
      .click();
    await expect(carousel(page)).toContainText(`${PHOTO_COUNT} of ${PHOTO_COUNT}`);
  });

  test('each photo has a descriptive accessible name', async ({ page }) => {
    for (let i = 1; i <= PHOTO_COUNT; i++) {
      await expect(currentPhoto(page)).toHaveAccessibleName(/photo \d+/i);
      await carousel(page)
        .getByRole('button', { name: /next/i })
        .click();
    }
  });

  test('carousel controls are keyboard operable and keep focus', async ({
    page,
  }) => {
    const next = carousel(page).getByRole('button', { name: /next/i });
    await next.focus();
    await page.keyboard.press('Enter');
    await expect(carousel(page)).toContainText(`2 of ${PHOTO_COUNT}`);
    // Focus is not lost when the photo changes.
    await expect(next).toBeFocused();
  });
});

import { test, expect } from '@playwright/test';

// Requirement: Path — the shopper sees where the shoe sits in the store, such
// as Shop, Trail, Trail Runner 2, and can go back to any earlier step.

test.describe('Breadcrumb path', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('shows the full path in a breadcrumb navigation landmark', async ({
    page,
  }) => {
    const breadcrumb = page.getByRole('navigation', { name: /breadcrumb/i });
    await expect(breadcrumb).toBeVisible();
    await expect(breadcrumb).toContainText('Shop');
    await expect(breadcrumb).toContainText('Trail');
    await expect(breadcrumb).toContainText('Trail Runner 2');
  });

  test('earlier steps are links the shopper can go back to', async ({
    page,
  }) => {
    const breadcrumb = page.getByRole('navigation', { name: /breadcrumb/i });
    for (const step of ['Shop', 'Trail']) {
      const link = breadcrumb.getByRole('link', { name: step, exact: true });
      await expect(link).toBeVisible();
      await expect(link).toHaveAttribute('href', /.+/);
    }
  });

  test('current step is marked as the current page and is not a link', async ({
    page,
  }) => {
    const breadcrumb = page.getByRole('navigation', { name: /breadcrumb/i });
    // APG breadcrumb: last item has aria-current="page" and is not actionable.
    const current = breadcrumb.getByText('Trail Runner 2', { exact: true });
    await expect(current).toHaveAttribute('aria-current', 'page');
    await expect(
      breadcrumb.getByRole('link', { name: 'Trail Runner 2' }),
    ).toHaveCount(0);
  });

  test('path items are presented in order', async ({ page }) => {
    const breadcrumb = page.getByRole('navigation', { name: /breadcrumb/i });
    const text = await breadcrumb.textContent();
    const shopIdx = text.indexOf('Shop');
    const trailIdx = text.indexOf('Trail');
    const productIdx = text.indexOf('Trail Runner 2');
    expect(shopIdx).toBeGreaterThanOrEqual(0);
    expect(trailIdx).toBeGreaterThan(shopIdx);
    expect(productIdx).toBeGreaterThan(trailIdx);
  });
});

import { test, expect } from '@playwright/test';

// Requirement: Color — the shopper can choose blue, black or grey; only the
// chosen color shows until they change it, each with a round swatch.

const COLORS = ['Blue', 'Black', 'Grey'];

test.describe('Color picker', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  function colorGroup(page) {
    return page.getByRole('radiogroup', { name: /color/i });
  }

  test('offers blue, black and grey as radio choices in a group', async ({
    page,
  }) => {
    const group = colorGroup(page);
    await expect(group).toBeVisible();
    for (const color of COLORS) {
      await expect(
        group.getByRole('radio', { name: color, exact: true }),
      ).toBeVisible();
    }
  });

  test('each color option has a round swatch', async ({ page }) => {
    for (const color of COLORS) {
      const swatch = page.getByTestId(`swatch-${color.toLowerCase()}`);
      await expect(swatch).toBeVisible();
      const box = await swatch.boundingBox();
      // Round: square box with a border-radius of at least 50%.
      expect(Math.abs(box.width - box.height)).toBeLessThanOrEqual(1);
      const radius = await swatch.evaluate(
        (el) => getComputedStyle(el).borderRadius,
      );
      const radiusPx = parseFloat(radius);
      expect(radiusPx).toBeGreaterThanOrEqual(box.width / 2 - 1);
    }
  });

  test('only the chosen color is shown as selected until it changes', async ({
    page,
  }) => {
    const group = colorGroup(page);
    await group.getByRole('radio', { name: 'Blue' }).check();
    await expect(group.getByRole('radio', { name: 'Blue' })).toBeChecked();
    await expect(
      group.getByRole('radio', { name: 'Black' }),
    ).not.toBeChecked();
    await expect(group.getByRole('radio', { name: 'Grey' })).not.toBeChecked();

    // The chosen color is the only one shown to the shopper.
    await expect(page.getByText(/selected color: blue/i)).toBeVisible();
    await expect(page.getByText(/selected color: black/i)).toBeHidden();
    await expect(page.getByText(/selected color: grey/i)).toBeHidden();

    await group.getByRole('radio', { name: 'Grey' }).check();
    await expect(group.getByRole('radio', { name: 'Grey' })).toBeChecked();
    await expect(group.getByRole('radio', { name: 'Blue' })).not.toBeChecked();
    await expect(page.getByText(/selected color: grey/i)).toBeVisible();
    await expect(page.getByText(/selected color: blue/i)).toBeHidden();
  });

  test('color options are operable with the keyboard (APG radio group)', async ({
    page,
  }) => {
    const blue = colorGroup(page).getByRole('radio', { name: 'Blue' });
    await blue.focus();
    // Arrow keys move selection within a radio group.
    await page.keyboard.press('ArrowDown');
    const black = colorGroup(page).getByRole('radio', { name: 'Black' });
    await expect(black).toBeChecked();
    await expect(black).toBeFocused();
  });
});

import { test, expect } from '@playwright/test';
import { SIZES, SOLD_OUT_SIZES } from './helpers.js';

// Requirement: Size — the shopper picks one size from a list that only opens
// when they want to change it; only the chosen size shows, and sold-out sizes
// can't be picked.
// Pattern: APG collapsible listbox (button with aria-haspopup="listbox").

test.describe('Size selector', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  function sizeButton(page) {
    return page.getByRole('button', { name: /^size/i });
  }

  test('list stays closed until the shopper wants to change the size', async ({
    page,
  }) => {
    await expect(sizeButton(page)).toHaveAttribute('aria-haspopup', 'listbox');
    await expect(sizeButton(page)).toHaveAttribute('aria-expanded', 'false');
    await expect(page.getByRole('listbox')).toBeHidden();
  });

  test('opens on click and shows all sizes', async ({ page }) => {
    await sizeButton(page).click();
    await expect(sizeButton(page)).toHaveAttribute('aria-expanded', 'true');
    const listbox = page.getByRole('listbox', { name: /size/i });
    await expect(listbox).toBeVisible();
    for (const size of SIZES) {
      await expect(
        listbox.getByRole('option', { name: size, exact: true }),
      ).toBeVisible();
    }
  });

  test('only the chosen size shows once picked, and the list closes', async ({
    page,
  }) => {
    await sizeButton(page).click();
    await page
      .getByRole('listbox', { name: /size/i })
      .getByRole('option', { name: 'US 8', exact: true })
      .click();
    await expect(page.getByRole('listbox')).toBeHidden();
    await expect(sizeButton(page)).toContainText('US 8');
    // Other sizes are not shown while the list is closed.
    await expect(page.getByText('US 7', { exact: true })).toBeHidden();
  });

  test('sold-out sizes are marked and cannot be picked', async ({ page }) => {
    await sizeButton(page).click();
    const listbox = page.getByRole('listbox', { name: /size/i });
    for (const size of SOLD_OUT_SIZES) {
      const option = listbox.getByRole('option', { name: new RegExp(size) });
      await expect(option).toHaveAttribute('aria-disabled', 'true');
      await expect(option).toContainText(/sold out/i);
      // Clicking a sold-out size does not select it and keeps the list open.
      await option.click({ force: true });
      await expect(listbox).toBeVisible();
      await expect(sizeButton(page)).not.toContainText(size);
    }
  });

  test('keyboard: opens with ArrowDown, moves with arrows, selects with Enter', async ({
    page,
  }) => {
    await sizeButton(page).focus();
    await page.keyboard.press('ArrowDown');
    const listbox = page.getByRole('listbox', { name: /size/i });
    await expect(listbox).toBeVisible();
    // Focus is on an option (APG: aria-activedescendant or roving focus).
    await page.keyboard.press('ArrowDown');
    await page.keyboard.press('Enter');
    await expect(listbox).toBeHidden();
    // The second size in the list was chosen.
    await expect(sizeButton(page)).toContainText(SIZES[1]);
    // Focus returns to the button after selection.
    await expect(sizeButton(page)).toBeFocused();
  });

  test('keyboard: Escape closes the list and returns focus to the button', async ({
    page,
  }) => {
    await sizeButton(page).click();
    await expect(page.getByRole('listbox', { name: /size/i })).toBeVisible();
    await page.keyboard.press('Escape');
    await expect(page.getByRole('listbox')).toBeHidden();
    await expect(sizeButton(page)).toBeFocused();
    await expect(sizeButton(page)).toHaveAttribute('aria-expanded', 'false');
  });

  test('sold-out sizes are skipped over / not selectable via keyboard', async ({
    page,
  }) => {
    await sizeButton(page).focus();
    await page.keyboard.press('ArrowDown');
    const listbox = page.getByRole('listbox', { name: /size/i });
    // Navigate to a sold-out size and try to select it.
    const soldOut = listbox.getByRole('option', {
      name: new RegExp(SOLD_OUT_SIZES[0]),
    });
    await soldOut.focus();
    await page.keyboard.press('Enter');
    await expect(sizeButton(page)).not.toContainText(SOLD_OUT_SIZES[0]);
  });
});

import { test, expect } from '@playwright/test';
import { expectNoA11yViolations } from './helpers.js';

// Requirement: Size guide — the shopper can open a size chart over the page
// from next to the size, enter their foot length and choose US or EU to get
// their size, and must close it to continue.
// Pattern: APG modal dialog.

test.describe('Size guide dialog', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  function trigger(page) {
    return page.getByRole('button', { name: /size guide/i });
  }

  function dialog(page) {
    return page.getByRole('dialog', { name: /size guide/i });
  }

  test('a size guide button sits next to the size selector', async ({
    page,
  }) => {
    await expect(trigger(page)).toBeVisible();
  });

  test('opens a modal dialog over the page', async ({ page }) => {
    await trigger(page).click();
    const dlg = dialog(page);
    await expect(dlg).toBeVisible();
    await expect(dlg).toHaveAttribute('aria-modal', 'true');
    // Focus moves into the dialog.
    await expect(dlg.locator(':focus')).toBeVisible();
  });

  test('the shopper enters foot length and chooses US or EU to get a size', async ({
    page,
  }) => {
    await trigger(page).click();
    const dlg = dialog(page);

    const unitGroup = dlg.getByRole('radiogroup', { name: /unit/i });
    await expect(unitGroup.getByRole('radio', { name: 'US' })).toBeVisible();
    await expect(unitGroup.getByRole('radio', { name: 'EU' })).toBeVisible();

    await dlg.getByLabel(/foot length/i).fill('26');
    await unitGroup.getByRole('radio', { name: 'US' }).check();
    await expect(dlg).toContainText(/your size: us 8/i);

    await unitGroup.getByRole('radio', { name: 'EU' }).check();
    await expect(dlg).toContainText(/your size: eu 41/i);
  });

  test('the dialog shows a size chart', async ({ page }) => {
    await trigger(page).click();
    const dlg = dialog(page);
    await expect(dlg.getByRole('table')).toBeVisible();
    await expect(dlg.getByRole('columnheader', { name: /us/i })).toBeVisible();
    await expect(dlg.getByRole('columnheader', { name: /eu/i })).toBeVisible();
  });

  test('the shopper must close the dialog to continue (modal)', async ({
    page,
  }) => {
    await trigger(page).click();
    await expect(dialog(page)).toBeVisible();
    // Content behind the dialog is inert: it cannot receive keyboard focus.
    const addToCart = page.getByRole('button', { name: /add to cart/i });
    await expect(addToCart).not.toBeFocused();
    // Tab cycles inside the dialog and never leaves it.
    for (let i = 0; i < 20; i++) {
      await page.keyboard.press('Tab');
      const inside = await page.evaluate(() => {
        const dlg = document.querySelector('[role="dialog"]');
        return dlg && dlg.contains(document.activeElement);
      });
      expect(inside).toBe(true);
    }
  });

  test('close button closes the dialog and returns focus to the trigger', async ({
    page,
  }) => {
    await trigger(page).click();
    await dialog(page)
      .getByRole('button', { name: /close/i })
      .click();
    await expect(dialog(page)).toBeHidden();
    await expect(trigger(page)).toBeFocused();
  });

  test('Escape closes the dialog and returns focus to the trigger', async ({
    page,
  }) => {
    await trigger(page).click();
    await expect(dialog(page)).toBeVisible();
    await page.keyboard.press('Escape');
    await expect(dialog(page)).toBeHidden();
    await expect(trigger(page)).toBeFocused();
  });

  test('open dialog has no WCAG 2.2 AA violations', async ({ page }) => {
    await trigger(page).click();
    await expect(dialog(page)).toBeVisible();
    await expectNoA11yViolations(page);
  });
});

import { test, expect } from '@playwright/test';

// Requirement: Quantity — the shopper can choose how many pairs to buy,
// typing the number or changing it by one.

test.describe('Quantity picker', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  function quantity(page) {
    return page.getByRole('spinbutton', { name: /quantity/i });
  }

  test('starts at one pair', async ({ page }) => {
    await expect(quantity(page)).toHaveValue('1');
  });

  test('the shopper can type the number of pairs', async ({ page }) => {
    await quantity(page).fill('3');
    await expect(quantity(page)).toHaveValue('3');
  });

  test('increase and decrease buttons change the quantity by one', async ({
    page,
  }) => {
    await page.getByRole('button', { name: /increase quantity/i }).click();
    await expect(quantity(page)).toHaveValue('2');
    await page.getByRole('button', { name: /increase quantity/i }).click();
    await expect(quantity(page)).toHaveValue('3');
    await page.getByRole('button', { name: /decrease quantity/i }).click();
    await expect(quantity(page)).toHaveValue('2');
  });

  test('quantity never goes below one', async ({ page }) => {
    await page.getByRole('button', { name: /decrease quantity/i }).click();
    await expect(quantity(page)).toHaveValue('1');
  });

  test('arrow keys on the spinbutton change the quantity by one', async ({
    page,
  }) => {
    await quantity(page).focus();
    await page.keyboard.press('ArrowUp');
    await expect(quantity(page)).toHaveValue('2');
    await page.keyboard.press('ArrowDown');
    await expect(quantity(page)).toHaveValue('1');
  });
});

import { test, expect } from '@playwright/test';

// Requirement: Wishlist — the shopper can save or unsave the shoe with a
// heart.
// Pattern: APG toggle button (aria-pressed).

test.describe('Wishlist', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  function wishlist(page) {
    return page.getByRole('button', { name: /wishlist/i });
  }

  test('has a wishlist toggle button with a heart', async ({ page }) => {
    const button = wishlist(page);
    await expect(button).toBeVisible();
    // The heart is part of the control (icon or text), not a bare image.
    await expect(button.locator('[data-icon="heart"]')).toBeVisible();
  });

  test('saves the shoe and communicates the pressed state', async ({
    page,
  }) => {
    const button = wishlist(page);
    await expect(button).toHaveAttribute('aria-pressed', 'false');
    await button.click();
    await expect(button).toHaveAttribute('aria-pressed', 'true');
  });

  test('unsaves the shoe when toggled again', async ({ page }) => {
    const button = wishlist(page);
    await button.click();
    await button.click();
    await expect(button).toHaveAttribute('aria-pressed', 'false');
  });

  test('is operable with the keyboard', async ({ page }) => {
    const button = wishlist(page);
    await button.focus();
    await page.keyboard.press('Enter');
    await expect(button).toHaveAttribute('aria-pressed', 'true');
    await page.keyboard.press('Space');
    await expect(button).toHaveAttribute('aria-pressed', 'false');
  });
});

import { test, expect } from '@playwright/test';

// Requirement: Add to cart — the shopper adds the shoe to the cart and sees a
// confirmation; without a size they are asked to pick one.

test.describe('Add to cart', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  function sizeButton(page) {
    return page.getByRole('button', { name: /^size/i });
  }

  async function pickSize(page, size) {
    await sizeButton(page).click();
    await page
      .getByRole('listbox', { name: /size/i })
      .getByRole('option', { name: size, exact: true })
      .click();
  }

  test('adding without a size asks the shopper to pick one', async ({
    page,
  }) => {
    await page.getByRole('button', { name: /add to cart/i }).click();
    // The request is announced assertively and does not get lost.
    const alert = page.getByRole('alert');
    await expect(alert).toBeVisible();
    await expect(alert).toContainText(/please (select|pick|choose) a size/i);
    // Nothing was added to the cart.
    const cart = page.getByRole('link', { name: /cart/i });
    await expect(cart).toContainText(/0/);
    // Focus moves to the size selector so the shopper can fix the problem.
    await expect(sizeButton(page)).toBeFocused();
  });

  test('adding with a size shows a confirmation', async ({ page }) => {
    await pickSize(page, 'US 8');
    await page.getByRole('button', { name: /add to cart/i }).click();
    // Polite live region announces the confirmation.
    const status = page.getByRole('status');
    await expect(status).toBeVisible();
    await expect(status).toContainText(/added to cart/i);
  });

  test('the cart count increases by the chosen quantity', async ({ page }) => {
    await pickSize(page, 'US 8');
    await page.getByRole('spinbutton', { name: /quantity/i }).fill('2');
    const cart = page.getByRole('link', { name: /cart/i });
    await expect(cart).toContainText(/0/);
    await page.getByRole('button', { name: /add to cart/i }).click();
    await expect(cart).toContainText(/2/);
  });

  test('the size prompt clears once a size is picked and added', async ({
    page,
  }) => {
    await page.getByRole('button', { name: /add to cart/i }).click();
    await expect(page.getByRole('alert')).toBeVisible();
    await pickSize(page, 'US 10');
    await page.getByRole('button', { name: /add to cart/i }).click();
    await expect(page.getByRole('alert')).toBeHidden();
    await expect(page.getByRole('status')).toContainText(/added to cart/i);
  });
});

import { test, expect } from '@playwright/test';

// Requirement: More information — details, reviews and shipping sit side by
// side below everything, with one section shown at a time.
// Pattern: APG tabs.

const TABS = ['Details', 'Reviews', 'Shipping'];

test.describe('More information tabs', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  function tablist(page) {
    return page.getByRole('tablist', { name: /product information/i });
  }

  test('details, reviews and shipping sit side by side as tabs', async ({
    page,
  }) => {
    const list = tablist(page);
    await expect(list).toBeVisible();
    for (const name of TABS) {
      await expect(
        list.getByRole('tab', { name, exact: true }),
      ).toBeVisible();
    }
    // Side by side: tabs share roughly the same vertical position.
    const boxes = await Promise.all(
      TABS.map((name) =>
        list.getByRole('tab', { name, exact: true }).boundingBox(),
      ),
    );
    expect(Math.abs(boxes[0].y - boxes[1].y)).toBeLessThanOrEqual(2);
    expect(Math.abs(boxes[1].y - boxes[2].y)).toBeLessThanOrEqual(2);
  });

  test('only one section is shown at a time', async ({ page }) => {
    const list = tablist(page);
    // Details is selected by default.
    await expect(
      list.getByRole('tab', { name: 'Details' }),
    ).toHaveAttribute('aria-selected', 'true');
    await expect(
      page.getByRole('tabpanel', { name: 'Details' }),
    ).toBeVisible();
    await expect(
      page.getByRole('tabpanel', { name: 'Reviews' }),
    ).toBeHidden();
    await expect(
      page.getByRole('tabpanel', { name: 'Shipping' }),
    ).toBeHidden();

    await list.getByRole('tab', { name: 'Reviews' }).click();
    await expect(
      page.getByRole('tabpanel', { name: 'Reviews' }),
    ).toBeVisible();
    await expect(
      page.getByRole('tabpanel', { name: 'Details' }),
    ).toBeHidden();
  });

  test('each tabpanel is labelled by its tab', async ({ page }) => {
    for (const name of TABS) {
      const tab = tablist(page).getByRole('tab', { name, exact: true });
      const controls = await tab.getAttribute('aria-controls');
      expect(controls).toBeTruthy();
      await expect(page.locator(`#${controls}`)).toHaveAttribute(
        'role',
        'tabpanel',
      );
    }
  });

  test('arrow keys move between tabs (APG tabs keyboard interaction)', async ({
    page,
  }) => {
    const list = tablist(page);
    await list.getByRole('tab', { name: 'Details' }).click();
    await page.keyboard.press('ArrowRight');
    const reviews = list.getByRole('tab', { name: 'Reviews' });
    await expect(reviews).toBeFocused();
    // Only the selected tab is in the tab order.
    await expect(reviews).toHaveAttribute('tabindex', /0|-1/);
    await page.keyboard.press('ArrowRight');
    await expect(list.getByRole('tab', { name: 'Shipping' })).toBeFocused();
    // Wraps around to the first tab.
    await page.keyboard.press('ArrowRight');
    await expect(list.getByRole('tab', { name: 'Details' })).toBeFocused();
  });

  test('activating a tab from the keyboard shows its section', async ({
    page,
  }) => {
    const list = tablist(page);
    await list.getByRole('tab', { name: 'Details' }).focus();
    await page.keyboard.press('ArrowRight');
    await page.keyboard.press('Enter');
    await expect(
      page.getByRole('tabpanel', { name: 'Reviews' }),
    ).toBeVisible();
  });
});

import { test, expect } from '@playwright/test';

// Requirement: Bottom of the page — the shopper finds customer help, company
