import { test, expect } from '@playwright/test';

// Requirement: Questions — a few common questions about the shoe, each with
// its answer hidden until the shopper opens it.
// Pattern: APG accordion.

const QUESTIONS = [
  'Is the Trail Runner 2 waterproof?',
  'How much does the shoe weigh?',
  'Can I return the shoes if they do not fit?',
];

test.describe('Common questions accordion', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('shows a few common questions about the shoe', async ({ page }) => {
    const faq = page.getByRole('region', { name: /questions/i });
    await expect(faq).toBeVisible();
    for (const question of QUESTIONS) {
      await expect(
        faq.getByRole('button', { name: question }),
      ).toBeVisible();
    }
  });

  test('answers are hidden until the shopper opens a question', async ({
    page,
  }) => {
    const faq = page.getByRole('region', { name: /questions/i });
    for (const question of QUESTIONS) {
      const button = faq.getByRole('button', { name: question });
      await expect(button).toHaveAttribute('aria-expanded', 'false');
      const panelId = await button.getAttribute('aria-controls');
      expect(panelId).toBeTruthy();
      await expect(page.locator(`#${panelId}`)).toBeHidden();
    }
  });

  test('opening a question reveals its answer', async ({ page }) => {
    const faq = page.getByRole('region', { name: /questions/i });
    const button = faq.getByRole('button', { name: QUESTIONS[0] });
    await button.click();
    await expect(button).toHaveAttribute('aria-expanded', 'true');
    const panelId = await button.getAttribute('aria-controls');
    const panel = page.locator(`#${panelId}`);
    await expect(panel).toBeVisible();
    await expect(panel).not.toBeEmpty();
  });

  test('each question opens independently', async ({ page }) => {
    const faq = page.getByRole('region', { name: /questions/i });
    const first = faq.getByRole('button', { name: QUESTIONS[0] });
    const second = faq.getByRole('button', { name: QUESTIONS[1] });
    await first.click();
    await second.click();
    await expect(first).toHaveAttribute('aria-expanded', 'true');
    await expect(second).toHaveAttribute('aria-expanded', 'true');
    // Opening again closes it.
    await first.click();
    await expect(first).toHaveAttribute('aria-expanded', 'false');
    await expect(second).toHaveAttribute('aria-expanded', 'true');
  });

  test('question buttons are keyboard operable', async ({ page }) => {
    const faq = page.getByRole('region', { name: /questions/i });
    const button = faq.getByRole('button', { name: QUESTIONS[2] });
    await button.focus();
    await page.keyboard.press('Enter');
    await expect(button).toHaveAttribute('aria-expanded', 'true');
    await page.keyboard.press('Space');
    await expect(button).toHaveAttribute('aria-expanded', 'false');
  });
});

import { test, expect } from '@playwright/test';
import { expectNoA11yViolations } from './helpers.js';

// Cross-cutting: WCAG 2.2 AA conformance and keyboard access for the whole page.

test.describe('Accessibility (WCAG 2.2 AA)', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('page has no automatically detectable WCAG 2.2 AA violations', async ({
    page,
  }) => {
    // Scan a fully rendered page, not an empty shell.
    await expect(page.getByRole('main')).toBeVisible();
    await expectNoA11yViolations(page);
  });

  test('page has exactly one h1 naming the product', async ({ page }) => {
    const h1 = page.getByRole('heading', { level: 1 });
    await expect(h1).toHaveCount(1);
    await expect(h1).toContainText('Trail Runner 2');
  });

  test('page is organised in landmarks: banner, main, contentinfo', async ({
    page,
  }) => {
    await expect(page.getByRole('banner')).toHaveCount(1);
    await expect(page.getByRole('main')).toHaveCount(1);
    await expect(page.getByRole('contentinfo')).toHaveCount(1);
  });

  test('the whole page can be used with the keyboard alone', async ({
    page,
  }) => {
    // Every focus stop lands on a visible, operable element.
    for (let i = 0; i < 40; i++) {
      await page.keyboard.press('Tab');
      const focused = page.locator(':focus');
      await expect(focused).toBeVisible();
    }
  });

  test('keyboard focus is always visible (WCAG 2.4.7 / 2.4.13)', async ({
    page,
  }) => {
    await page.keyboard.press('Tab');
    const indicator = await page.evaluate(() => {
      const el = document.activeElement;
      const style = getComputedStyle(el);
      const outlineVisible =
        style.outlineStyle !== 'none' && parseFloat(style.outlineWidth) > 0;
      const shadowVisible =
        style.boxShadow !== 'none' && style.boxShadow !== '';
      return { outlineVisible, shadowVisible, tag: el.tagName };
    });
    expect(
      indicator.outlineVisible || indicator.shadowVisible,
      `focused <${indicator.tag}> has no visible focus indicator`,
    ).toBe(true);
  });

  test('no positive tabindex values anywhere (WCAG 2.4.3 focus order)', async ({
    page,
  }) => {
    // The page must actually have interactive elements to check.
    await expect(page.getByRole('button').first()).toBeVisible();
    const offenders = await page.evaluate(() =>
      Array.from(document.querySelectorAll('[tabindex]'))
        .filter((el) => parseInt(el.getAttribute('tabindex'), 10) > 0)
        .map((el) => el.outerHTML),
    );
    expect(offenders).toEqual([]);
  });

  test('images have alternative text', async ({ page }) => {
    // The page must actually render images (product photos) to check.
    await expect(page.locator('img').first()).toBeVisible();
    const missing = await page.evaluate(() =>
      Array.from(document.querySelectorAll('img:not([alt])')).map(
        (img) => img.outerHTML,
      ),
    );
    expect(missing).toEqual([]);
  });

  test('page works at 200% zoom without loss of content (WCAG 1.4.4)', async ({
    page,
  }) => {
    await page.setViewportSize({ width: 640, height: 480 });
    await page.evaluate(() => {
      document.body.style.zoom = '2';
    });
    await expect(
      page.getByRole('heading', { name: 'Trail Runner 2', level: 1 }),
    ).toBeVisible();
    await expect(
      page.getByRole('button', { name: /add to cart/i }),
    ).toBeVisible();
  });
});

args.streamContent:
:root {
  --text: #212529;
  --muted: #4a5568;
  --accent: #0b5fff;
  --surface: #ffffff;
  --border: #cbd2d9;
  --danger: #b00020;
  --success: #1b5e20;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica,
    Arial, sans-serif;
  color: var(--text);
  background: var(--surface);
  line-height: 1.5;
}

:focus {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

/* Header */
.site-header {
  display: flex;
  align-items: center;
  gap: 2rem;
  padding: 0.75rem 1.5rem;
  border-bottom: 1px solid var(--border);
}

.site-header .logo {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--text);
  text-decoration: none;
}

.main-nav ul {
  display: flex;
  gap: 1.25rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.main-nav a,
.cart-link {
  color: var(--text);
  text-decoration: none;
  font-weight: 600;
}

.main-nav a:hover,
.cart-link:hover {
  text-decoration: underline;
}

.cart-link {
  margin-left: auto;
}

/* Layout */
main {
  max-width: 1100px;
  margin: 0 auto;
  padding: 1rem 1.5rem 3rem;
}

/* Breadcrumb */
.breadcrumb ol {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  list-style: none;
  margin: 0.5rem 0 1rem;
  padding: 0;
  color: var(--muted);
}

.breadcrumb li + li::before {
  content: "/";
  margin-right: 0.5rem;
  color: var(--muted);
}

/* Product layout */
.product {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 2rem;
  align-items: start;
}

@media (max-width: 800px) {
  .product {
    grid-template-columns: 1fr;
  }
}

/* Carousel */
.carousel {
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 1rem;
  background: #f7f8fa;
}

.carousel img {
  display: block;
  width: 100%;
  height: auto;
  border-radius: 6px;
}

.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 0.75rem;
}

.carousel-status {
  color: var(--muted);
  margin: 0;
}

/* Buttons */
button {
  font: inherit;
  cursor: pointer;
}

.btn {
  border: 1px solid var(--border);
  background: #fff;
  color: var(--text);
  border-radius: 6px;
  padding: 0.5rem 0.9rem;
}

.btn-primary {
  background: #1a202c;
  border-color: #1a202c;
  color: #fff;
  padding: 0.75rem 1.5rem;
  font-weight: 700;
}

/* Product info */
.product-info h1 {
  margin: 0 0 0.5rem;
  font-size: 2rem;
}

.price-row {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  position: relative;
}

.price {
  font-size: 1.4rem;
  font-weight: 700;
}

.info-button {
  border: 1px solid var(--border);
  border-radius: 50%;
  width: 1.5rem;
  height: 1.5rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: #fff;
  color: var(--muted);
  font-weight: 700;
  padding: 0;
}

.tooltip {
  position: absolute;
  top: 100%;
  left: 0;
  z-index: 20;
  background: #1a202c;
  color: #fff;
  padding: 0.4rem 0.6rem;
  border-radius: 6px;
  font-size: 0.85rem;
  max-width: 16rem;
}

/* Color picker */
.option-group {
  margin: 1rem 0;
}

.option-group .group-label {
  font-weight: 700;
  display: block;
  margin-bottom: 0.4rem;
}

.color-options {
  display: flex;
  gap: 1rem;
}

.color-option {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  cursor: pointer;
}

.swatch {
  display: inline-block;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  border: 2px solid var(--border);
}

.selected-color {
  color: var(--muted);
  margin: 0.25rem 0 0;
}

/* Size selector */
.size-row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.size-select {
  position: relative;
}

.size-listbox {
  position: absolute;
  z-index: 30;
  top: 100%;
  left: 0;
  margin: 0.25rem 0 0;
  padding: 0.25rem;
