import { useEffect, useRef, useState } from 'react';
import './styles.css';

const COLORS = [
  { name: 'Blue', hex: '#2b6cb0' },
  { name: 'Black', hex: '#1a202c' },
  { name: 'Grey', hex: '#718096' },
];

const SIZES = ['US 7', 'US 8', 'US 9', 'US 10', 'US 11', 'US 12'];
const SOLD_OUT_SIZES = ['US 9', 'US 11'];

const SIZE_CHART = [
  { cm: 24, us: '6', eu: '38' },
  { cm: 24.5, us: '6.5', eu: '39' },
  { cm: 25, us: '7', eu: '40' },
  { cm: 25.5, us: '7.5', eu: '40.5' },
  { cm: 26, us: '8', eu: '41' },
  { cm: 26.5, us: '8.5', eu: '42' },
  { cm: 27, us: '9', eu: '42.5' },
  { cm: 27.5, us: '9.5', eu: '43' },
  { cm: 28, us: '10', eu: '44' },
  { cm: 28.5, us: '10.5', eu: '44.5' },
  { cm: 29, us: '11', eu: '45' },
  { cm: 29.5, us: '11.5', eu: '45.5' },
  { cm: 30, us: '12', eu: '46' },
];

function photoSrc(bg, label) {
  const svg =
    `<svg xmlns="http://www.w3.org/2000/svg" width="480" height="360" viewBox="0 0 480 360">` +
    `<rect width="480" height="360" fill="${bg}"/>` +
    `<text x="240" y="185" fill="#ffffff" font-family="sans-serif" font-size="30" text-anchor="middle">${label}</text>` +
    `</svg>`;
  return `data:image/svg+xml,${encodeURIComponent(svg)}`;
}

const PHOTOS = [
  { src: photoSrc('#2b6cb0', 'Trail Runner 2 — side view'), alt: 'Trail Runner 2 photo 1' },
  { src: photoSrc('#1a202c', 'Trail Runner 2 — top view'), alt: 'Trail Runner 2 photo 2' },
  { src: photoSrc('#4a5568', 'Trail Runner 2 — sole view'), alt: 'Trail Runner 2 photo 3' },
];

const TABS = [
  {
    id: 'details',
    label: 'Details',
    content:
      'The Trail Runner 2 is built for rough terrain: a grippy lugged outsole, breathable ripstop upper and a responsive cushioned midsole keep you fast and stable on any trail.',
  },
  {
    id: 'reviews',
    label: 'Reviews',
    content:
      'Runners love the secure fit and traction. "Best trail shoe I have owned — light, tough and comfortable straight out of the box."',
  },
  {
    id: 'shipping',
    label: 'Shipping',
    content:
      'Free standard shipping on orders over $75. Express delivery available at checkout. Free returns within 30 days.',
  },
];

function getTabbables(container) {
  const tabbables = [];
  const seenRadioGroups = new Set();
  const candidates = container.querySelectorAll(
    'a[href], button, input, select, textarea, [tabindex]',
  );
  for (const el of candidates) {
    if (el.disabled) continue;
    const tabIndex = el.getAttribute('tabindex');
    if (tabIndex !== null && Number.parseInt(tabIndex, 10) < 0) continue;
    if (el.type === 'radio') {
      // A radio group is a single tab stop: the checked radio, or the first.
      if (seenRadioGroups.has(el.name)) continue;
      seenRadioGroups.add(el.name);
      const group = Array.from(
        container.querySelectorAll(
          `input[type="radio"][name="${CSS.escape(el.name)}"]`,
        ),
      ).filter((radio) => !radio.disabled);
      const representative = group.find((radio) => radio.checked) || group[0];
      if (representative) tabbables.push(representative);
      continue;
    }
    tabbables.push(el);
  }
  return tabbables;
}

const FAQS = [
  {
    question: 'Is the Trail Runner 2 waterproof?',
    answer:
      'The upper is water-repellent and sheds light rain and splashes, but the shoe is not fully waterproof. For wet conditions we recommend pairing it with waterproof socks.',
  },
  {
    question: 'How much does the shoe weigh?',
    answer:
      'A single shoe weighs 285 g in US 9, making it one of the lightest fully lugged trail shoes in its class.',
  },
  {
    question: 'Can I return the shoes if they do not fit?',
    answer:
      'Yes. You can return unworn shoes within 30 days for a full refund, and exchanges for a different size are free.',
  },
  {
    question: 'Are the materials vegan?',
    answer:
      'Yes. The Trail Runner 2 uses no animal-derived materials: the upper, glues and dyes are all synthetic or plant-based.',
  },
];

export default function App() {
  // Store / cart
  const [cartCount, setCartCount] = useState(0);

  // Photos
  const [photoIndex, setPhotoIndex] = useState(0);

  // Price tooltip
  const [tooltipOpen, setTooltipOpen] = useState(false);

  // Color
  const [color, setColor] = useState('Blue');

  // Size selector (collapsible listbox)
  const [size, setSize] = useState(null);
  const [sizeOpen, setSizeOpen] = useState(false);
  const sizeButtonRef = useRef(null);
  const optionRefs = useRef([]);
  const focusFirstOption = useRef(false);

  // Size guide dialog
  const [guideOpen, setGuideOpen] = useState(false);
  const guideTriggerRef = useRef(null);
  const dialogRef = useRef(null);
  const dialogCloseRef = useRef(null);
  const [footLength, setFootLength] = useState('');
  const [unit, setUnit] = useState('');

  // Quantity
  const [quantity, setQuantity] = useState('1');

  // Add to cart feedback
  const [error, setError] = useState('');
  const [status, setStatus] = useState('');

  // Wishlist
  const [saved, setSaved] = useState(false);

  // Tabs
  const [activeTab, setActiveTab] = useState('details');
  const tabRefs = useRef([]);

  // FAQ
  const [openFaqs, setOpenFaqs] = useState(() => new Set());

  // Focus the first size option when the listbox is opened from the keyboard.
  useEffect(() => {
    if (sizeOpen && focusFirstOption.current) {
      focusFirstOption.current = false;
      optionRefs.current[0]?.focus();
    }
  }, [sizeOpen]);

  // Move focus into the size guide dialog when it opens.
  useEffect(() => {
    if (guideOpen) {
      dialogCloseRef.current?.focus();
    }
  }, [guideOpen]);

  function chooseSize(value) {
    if (SOLD_OUT_SIZES.includes(value)) {
      // Sold-out sizes cannot be picked; the list stays open.
      return;
    }
    setSize(value);
    setSizeOpen(false);
    sizeButtonRef.current?.focus();
  }

  function onSizeKeyDown(event) {
    if (event.key === 'Escape' && sizeOpen) {
      event.preventDefault();
      setSizeOpen(false);
      sizeButtonRef.current?.focus();
      return;
    }
    if (event.target === sizeButtonRef.current) {
      if (
        (event.key === 'ArrowDown' || event.key === 'ArrowUp') &&
        !sizeOpen
      ) {
        event.preventDefault();
        focusFirstOption.current = true;
        setSizeOpen(true);
      }
      return;
    }
    const index = optionRefs.current.indexOf(event.target);
    if (index === -1) return;
    if (event.key === 'ArrowDown') {
      event.preventDefault();
      optionRefs.current[(index + 1) % SIZES.length]?.focus();
    } else if (event.key === 'ArrowUp') {
      event.preventDefault();
      optionRefs.current[(index - 1 + SIZES.length) % SIZES.length]?.focus();
    } else if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      chooseSize(SIZES[index]);
    }
  }

  function closeGuide() {
    setGuideOpen(false);
    guideTriggerRef.current?.focus();
  }

  function onDialogKeyDown(event) {
    if (event.key === 'Escape') {
      event.preventDefault();
      closeGuide();
      return;
    }
    if (event.key !== 'Tab') return;
    const dialog = dialogRef.current;
    if (!dialog) return;
    const tabbables = getTabbables(dialog);
    if (tabbables.length === 0) return;
    const first = tabbables[0];
    const last = tabbables[tabbables.length - 1];
    const active = document.activeElement;
    if (!tabbables.includes(active)) {
      // Focus is outside the cycle (e.g. on a non-tabbable radio): pull it in.
      event.preventDefault();
      (event.shiftKey ? last : first).focus();
    } else if (event.shiftKey && active === first) {
      event.preventDefault();
      last.focus();
    } else if (!event.shiftKey && active === last) {
      event.preventDefault();
      first.focus();
    }
  }

  function recommendedSize() {
    const cm = parseFloat(footLength);
    if (!footLength || Number.isNaN(cm) || !unit) return null;
    let best = SIZE_CHART[0];
    for (const row of SIZE_CHART) {
      if (Math.abs(row.cm - cm) < Math.abs(best.cm - cm)) best = row;
    }
    return unit === 'US' ? `US ${best.us}` : `EU ${best.eu}`;
  }

  function changeQuantity(delta) {
    setQuantity((q) => {
      const value = Number.parseInt(q, 10);
      const next = (Number.isNaN(value) ? 1 : value) + delta;
      return String(Math.max(1, next));
    });
  }

  function addToCart() {
    if (!size) {
      setStatus('');
      setError('Please select a size before adding to cart.');
      sizeButtonRef.current?.focus();
      return;
    }
    setError('');
    const count = Math.max(1, Number.parseInt(quantity, 10) || 1);
    setCartCount((c) => c + count);
    setStatus(
      `${count} × Trail Runner 2 (${color}, ${size}) added to cart.`,
    );
  }

  function onTabListKeyDown(event) {
    const index = tabRefs.current.indexOf(event.target);
    if (index === -1) return;
    let next = null;
    if (event.key === 'ArrowRight') next = (index + 1) % TABS.length;
    else if (event.key === 'ArrowLeft')
      next = (index - 1 + TABS.length) % TABS.length;
    else if (event.key === 'Home') next = 0;
    else if (event.key === 'End') next = TABS.length - 1;
    if (next !== null) {
      event.preventDefault();
      tabRefs.current[next]?.focus();
    }
  }

  function toggleFaq(index) {
    setOpenFaqs((prev) => {
      const next = new Set(prev);
      if (next.has(index)) next.delete(index);
      else next.add(index);
      return next;
    });
  }

  const result = recommendedSize();

  return (
    <>
      <header className="site-header">
        <a className="logo" href="/">
          Stride
        </a>
        <nav aria-label="Main" className="main-nav">
          <ul>
            <li>
              <a href="/men">Men</a>
            </li>
            <li>
              <a href="/women">Women</a>
            </li>
            <li>
              <a href="/kids">Kids</a>
            </li>
          </ul>
        </nav>
        <a className="header-link" href="/search">
          Search
        </a>
        <a className="header-link" href="/account">
          Account
        </a>
        <a className="cart-link" href="/cart">
          Cart ({cartCount})
        </a>
      </header>

      <main>
        <nav aria-label="Breadcrumb" className="breadcrumb">
          <ol>
            <li>
              <a href="/shop">Shop</a>
            </li>
            <li>
              <a href="/shop/trail">Trail</a>
            </li>
            <li>
              <span aria-current="page">Trail Runner 2</span>
            </li>
          </ol>
        </nav>

        <div className="product">
          <section aria-label="Product photos" className="carousel">
            <img src={PHOTOS[photoIndex].src} alt={PHOTOS[photoIndex].alt} />
            <div className="carousel-controls">
              <button
                type="button"
                className="btn"
                onClick={() =>
                  setPhotoIndex(
                    (photoIndex - 1 + PHOTOS.length) % PHOTOS.length,
                  )
                }
              >
                Previous photo
              </button>
              <p className="carousel-status" aria-live="polite">
                {photoIndex + 1} of {PHOTOS.length}
              </p>
              <button
                type="button"
                className="btn"
                onClick={() => setPhotoIndex((photoIndex + 1) % PHOTOS.length)}
              >
                Next photo
              </button>
            </div>
            <div className="carousel-dots" role="group" aria-label="Choose photo">
              {PHOTOS.map((photo, index) => (
                <button
                  key={photo.alt}
                  type="button"
                  className="dot"
                  aria-label={`Go to photo ${index + 1}`}
                  aria-current={index === photoIndex ? 'true' : undefined}
                  onClick={() => setPhotoIndex(index)}
                >
                  {index + 1}
                </button>
              ))}
            </div>
          </section>

          <section aria-label="Product details" className="product-info">
            <h1>Trail Runner 2</h1>

            <div className="price-row">
              <p className="price">$120</p>
              <button
                type="button"
                className="info-button"
                aria-describedby="price-tooltip"
                onMouseEnter={() => setTooltipOpen(true)}
                onMouseLeave={() => setTooltipOpen(false)}
                onFocus={() => setTooltipOpen(true)}
                onBlur={() => setTooltipOpen(false)}
                onKeyDown={(event) => {
                  if (event.key === 'Escape') setTooltipOpen(false);
                }}
              >
                <span aria-hidden="true">i</span>
                <span className="visually-hidden">Price information</span>
              </button>
              <div
                id="price-tooltip"
                role="tooltip"
                className="tooltip"
                hidden={!tooltipOpen}
              >
                The price includes all applicable taxes.
              </div>
            </div>

            <div className="option-group">
              <span className="group-label" id="color-label">
                Color
              </span>
              <div
                role="radiogroup"
                aria-labelledby="color-label"
                className="color-options"
              >
                {COLORS.map(({ name, hex }) => (
                  <label key={name} className="color-option">
                    <input
                      type="radio"
                      name="color"
                      value={name}
                      checked={color === name}
                      onChange={() => setColor(name)}
                    />
                    <span
                      className="swatch"
                      data-testid={`swatch-${name.toLowerCase()}`}
                      style={{ backgroundColor: hex }}
                      aria-hidden="true"
                    />
                    {name}
                  </label>
                ))}
              </div>
              <p className="selected-color">Selected color: {color}</p>
            </div>

            <div className="option-group">
              <div className="size-row">
                <div className="size-select" onKeyDown={onSizeKeyDown}>
                  <button
                    type="button"
                    ref={sizeButtonRef}
                    className="btn"
                    aria-haspopup="listbox"
                    aria-expanded={sizeOpen}
                    onClick={() => setSizeOpen((open) => !open)}
                  >
                    {size ? `Size: ${size}` : 'Size: Select'}
                  </button>
                  {sizeOpen && (
                    <ul role="listbox" aria-label="Sizes" className="size-listbox">
                      {SIZES.map((value, index) => {
                        const soldOut = SOLD_OUT_SIZES.includes(value);
                        return (
                          <li
                            key={value}
                            role="option"
                            tabIndex={-1}
                            ref={(el) => {
                              optionRefs.current[index] = el;
                            }}
                            aria-selected={size === value}
                            aria-disabled={soldOut || undefined}
                            onClick={() => chooseSize(value)}
                          >
                            {value}
                            {soldOut && (
                              <span className="sold-out" aria-hidden="true">
                                sold out
                              </span>
                            )}
                          </li>
                        );
                      })}
                    </ul>
                  )}
                </div>
                <button
                  type="button"
                  ref={guideTriggerRef}
                  className="btn"
                  aria-label="Open size guide"
                  onClick={() => setGuideOpen(true)}
                >
                  Size guide
                </button>
              </div>
            </div>

            <div className="quantity-row">
              <button
                type="button"
                className="btn"
                onClick={() => changeQuantity(-1)}
              >
                <span aria-hidden="true">−</span>
                <span className="visually-hidden">Decrease quantity</span>
              </button>
              <input
                type="number"
                min="1"
                value={quantity}
                aria-label="Quantity"
                onChange={(event) => setQuantity(event.target.value)}
              />
              <button
                type="button"
                className="btn"
                onClick={() => changeQuantity(1)}
              >
                <span aria-hidden="true">+</span>
                <span className="visually-hidden">Increase quantity</span>
              </button>
            </div>

            <div className="actions">
              <button type="button" className="btn btn-primary" onClick={addToCart}>
                Add to cart
              </button>
              <button
                type="button"
                className="btn wishlist"
                aria-pressed={saved}
                onClick={() => setSaved((value) => !value)}
              >
                <span data-icon="heart" aria-hidden="true">
                  ♥
                </span>
                {saved ? 'Saved to wishlist' : 'Add to wishlist'}
              </button>
            </div>

            {error && (
              <p role="alert" className="alert">
                {error}
              </p>
            )}
            {status && (
              <p role="status" className="status">
                {status}
              </p>
            )}
          </section>
        </div>

        <section aria-label="More information" className="more-info">
          <div
            role="tablist"
            aria-label="Product information"
            onKeyDown={onTabListKeyDown}
          >
            {TABS.map((tab, index) => (
              <button
                key={tab.id}
                type="button"
                role="tab"
                id={`tab-${tab.id}`}
                ref={(el) => {
                  tabRefs.current[index] = el;
                }}
                aria-selected={activeTab === tab.id}
                aria-controls={`panel-${tab.id}`}
                tabIndex={activeTab === tab.id ? 0 : -1}
                onClick={() => setActiveTab(tab.id)}
              >
                {tab.label}
              </button>
            ))}
          </div>
          {TABS.map((tab) => (
            <div
              key={tab.id}
              role="tabpanel"
              id={`panel-${tab.id}`}
              aria-labelledby={`tab-${tab.id}`}
              hidden={activeTab !== tab.id}
            >
              <p>{tab.content}</p>
            </div>
          ))}
        </section>

        <section aria-labelledby="faq-heading" className="faq">
          <h2 id="faq-heading">Common questions</h2>
          {FAQS.map((faq, index) => {
            const open = openFaqs.has(index);
            return (
              <div className="faq-item" key={faq.question}>
                <h3>
                  <button
                    type="button"
                    className="faq-question"
                    aria-expanded={open}
                    aria-controls={`faq-panel-${index}`}
                    onClick={() => toggleFaq(index)}
                  >
                    {faq.question}
                    <span aria-hidden="true">{open ? '−' : '+'}</span>
                  </button>
                </h3>
                <div id={`faq-panel-${index}`} hidden={!open}>
                  <p className="faq-answer">{faq.answer}</p>
                </div>
              </div>
            );
          })}
        </section>

        {guideOpen && (
          <div className="dialog-overlay" onKeyDown={onDialogKeyDown}>
            <div
              role="dialog"
              aria-modal="true"
              aria-labelledby="size-guide-title"
              className="dialog"
              ref={dialogRef}
            >
              <h2 id="size-guide-title">Size guide</h2>
              <button type="button" className="btn" ref={dialogCloseRef} onClick={closeGuide}>
                Close size guide
              </button>

              <table>
                <thead>
                  <tr>
                    <th scope="col">Foot length (cm)</th>
                    <th scope="col">US</th>
                    <th scope="col">EU</th>
                  </tr>
                </thead>
                <tbody>
                  {SIZE_CHART.map((row) => (
                    <tr key={row.cm}>
                      <td>{row.cm}</td>
                      <td>{row.us}</td>
                      <td>{row.eu}</td>
                    </tr>
                  ))}
                </tbody>
              </table>

              <div className="converter">
                <label htmlFor="foot-length">Foot length (cm)</label>
                <input
                  id="foot-length"
                  type="text"
                  inputMode="decimal"
                  value={footLength}
                  onChange={(event) => setFootLength(event.target.value)}
                />
                <fieldset
                  className="unit-options"
                  role="radiogroup"
                  aria-label="Unit"
                >
                  <legend className="visually-hidden">Unit</legend>
                  <label>
                    <input
                      type="radio"
                      name="unit"
                      value="US"
                      checked={unit === 'US'}
                      onChange={() => setUnit('US')}
                    />
                    US
                  </label>
                  <label>
                    <input
                      type="radio"
                      name="unit"
                      value="EU"
                      checked={unit === 'EU'}
                      onChange={() => setUnit('EU')}
                    />
                    EU
                  </label>
                </fieldset>
              </div>

              {result && <p className="size-result">Your size: {result}</p>}
            </div>
          </div>
        )}
      </main>

      <footer className="site-footer">
        <div className="footer-columns">
          <section>
            <h2>Customer help</h2>
            <ul>
              <li>
                <a href="/help/contact">Contact us</a>
              </li>
              <li>
                <a href="/help/faq">FAQ</a>
              </li>
              <li>
                <a href="/help/returns">Returns</a>
              </li>
            </ul>
          </section>
          <section>
            <h2>Company</h2>
            <ul>
              <li>
                <a href="/about">About Stride</a>
              </li>
              <li>
                <a href="/careers">Careers</a>
              </li>
              <li>
                <a href="/press">Press</a>
              </li>
            </ul>
          </section>
          <section>
            <h2>Social media</h2>
            <ul>
              <li>
                <a href="https://www.instagram.com/stride">Instagram</a>
              </li>
              <li>
                <a href="https://www.facebook.com/stride">Facebook</a>
              </li>
              <li>
                <a href="https://www.youtube.com/stride">YouTube</a>
              </li>
            </ul>
          </section>
        </div>
      </footer>
    </>
  );
}

