:root {
  --text: #212529;
  --muted: #4a5568;
  --accent: #0b5fff;
  --surface: #ffffff;
  --border: #cbd2d9;
  --danger: #b00020;
  --success: #1b5e20;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica,
    Arial, sans-serif;
  color: var(--text);
  background: var(--surface);
  line-height: 1.5;
}

:focus {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

/* Header */
.site-header {
  display: flex;
  align-items: center;
  gap: 2rem;
  padding: 0.75rem 1.5rem;
  border-bottom: 1px solid var(--border);
}

.site-header .logo {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--text);
  text-decoration: none;
}

.main-nav ul {
  display: flex;
  gap: 1.25rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.main-nav a,
.cart-link {
  color: var(--text);
  text-decoration: none;
  font-weight: 600;
}

.main-nav a:hover,
.cart-link:hover {
  text-decoration: underline;
}

.cart-link {
  margin-left: auto;
}

.site-search {
  margin-left: auto;
}

.site-search + .cart-link {
  margin-left: 0;
}

.site-search input {
  font: inherit;
  padding: 0.4rem 0.7rem;
  border: 1px solid var(--border);
  border-radius: 6px;
}

::placeholder {
  color: #595959;
  opacity: 1;
}

/* Layout */
main {
  max-width: 1100px;
  margin: 0 auto;
  padding: 1rem 1.5rem 3rem;
}

/* Breadcrumb */
.breadcrumb ol {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  list-style: none;
  margin: 0.5rem 0 1rem;
  padding: 0;
  color: var(--muted);
}

.breadcrumb li + li::before {
  content: "/";
  margin-right: 0.5rem;
  color: var(--muted);
}

/* Product layout */
.product {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 2rem;
  align-items: start;
}

@media (max-width: 800px) {
  .product {
    grid-template-columns: 1fr;
  }
}

/* Carousel */
.carousel {
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 1rem;
  background: #f7f8fa;
}

.carousel img {
  display: block;
  width: 100%;
  height: auto;
  border-radius: 6px;
}

.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 0.75rem;
}

.carousel-status {
  color: var(--muted);
  margin: 0;
}

/* Buttons */
button {
  font: inherit;
  cursor: pointer;
}

.btn {
  border: 1px solid var(--border);
  background: #fff;
  color: var(--text);
  border-radius: 6px;
  padding: 0.5rem 0.9rem;
}

.btn-primary {
  background: #1a202c;
  border-color: #1a202c;
  color: #fff;
  padding: 0.75rem 1.5rem;
  font-weight: 700;
}

/* Product info */
.product-info h1 {
  margin: 0 0 0.5rem;
  font-size: 2rem;
}

.price-row {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  position: relative;
}

.price {
  font-size: 1.4rem;
  font-weight: 700;
}

.info-button {
  border: 1px solid var(--border);
  border-radius: 50%;
  width: 1.5rem;
  height: 1.5rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: #fff;
  color: var(--muted);
  font-weight: 700;
  padding: 0;
}

.tooltip {
  position: absolute;
  top: 100%;
  left: 0;
  z-index: 20;
  background: #1a202c;
  color: #fff;
  padding: 0.4rem 0.6rem;
  border-radius: 6px;
  font-size: 0.85rem;
  max-width: 16rem;
}

/* Color picker */
.option-group {
  margin: 1rem 0;
}

.option-group .group-label {
  font-weight: 700;
  display: block;
  margin-bottom: 0.4rem;
}

.color-options {
  display: flex;
  gap: 1rem;
}

.color-option {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  cursor: pointer;
}

.swatch {
  display: inline-block;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  border: 2px solid var(--border);
}

.selected-color {
  color: var(--muted);
  margin: 0.25rem 0 0;
}

/* Size selector */
.size-row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.size-select {
  position: relative;
}

.size-listbox {
  position: absolute;
  z-index: 30;
  top: 100%;
  left: 0;
  margin: 0.25rem 0 0;
  padding: 0.25rem;
  list-style: none;
  background: #fff;
  border: 1px solid var(--border);
  border-radius: 6px;
  min-width: 12rem;
  box-shadow: 0 8px 24px rgb(0 0 0 / 0.15);
}

.size-listbox [role="option"] {
  padding: 0.5rem 0.75rem;
  border-radius: 4px;
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  cursor: pointer;
}

.size-listbox [role="option"]:hover,
.size-listbox [role="option"]:focus {
  background: #eef3ff;
}

.size-listbox [role="option"][aria-selected="true"] {
  font-weight: 700;
}

.size-listbox [role="option"][aria-disabled="true"] {
  color: var(--muted);
  cursor: not-allowed;
}

.sold-out {
  font-size: 0.85rem;
  color: var(--muted);
}

/* Quantity */
.quantity-row {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin: 1rem 0;
}

.quantity-row input[type="number"] {
  width: 4rem;
  padding: 0.4rem;
  font: inherit;
  border: 1px solid var(--border);
  border-radius: 6px;
  text-align: center;
}

/* Actions */
.actions {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin: 1rem 0;
}

.wishlist {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
}

.wishlist [data-icon="heart"] {
  font-size: 1.25rem;
  color: #b00020;
}

.alert {
  color: var(--danger);
  font-weight: 600;
}

.status {
  color: var(--success);
  font-weight: 600;
}

/* Tabs */
.more-info {
  margin-top: 2.5rem;
}

[role="tablist"] {
  display: flex;
  gap: 0.25rem;
  border-bottom: 1px solid var(--border);
}

[role="tab"] {
  border: 1px solid transparent;
  border-bottom: none;
  background: none;
  padding: 0.6rem 1.2rem;
  font-weight: 600;
  color: var(--muted);
  border-radius: 6px 6px 0 0;
}

[role="tab"][aria-selected="true"] {
  color: var(--text);
  background: #fff;
  border-color: var(--border);
  margin-bottom: -1px;
}

[role="tabpanel"] {
  padding: 1rem 0.25rem;
}

/* FAQ */
.faq {
  margin-top: 2.5rem;
}

.faq-item {
  border-bottom: 1px solid var(--border);
}

.faq-item h3 {
  margin: 0;
}

.faq-question {
  width: 100%;
  background: none;
  border: none;
  text-align: left;
  padding: 0.9rem 0.25rem;
  font-weight: 600;
  display: flex;
  justify-content: space-between;
}

.faq-answer {
  padding: 0 0.25rem 0.9rem;
  margin: 0;
  color: var(--muted);
}

/* Dialog */
.dialog-overlay {
  position: fixed;
  inset: 0;
  background: rgb(0 0 0 / 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 100;
  padding: 1rem;
}

.dialog {
  background: #fff;
  border-radius: 10px;
  padding: 1.5rem;
  max-width: 34rem;
  width: 100%;
  max-height: 85vh;
  overflow: auto;
}

.dialog h2 {
  margin-top: 0;
}

.dialog table {
  border-collapse: collapse;
  margin: 1rem 0;
  width: 100%;
}

.dialog th,
.dialog td {
  border: 1px solid var(--border);
  padding: 0.4rem 0.6rem;
  text-align: left;
}

.converter {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem;
  margin: 1rem 0;
}

.converter input {
  width: 6rem;
  padding: 0.4rem;
  font: inherit;
  border: 1px solid var(--border);
  border-radius: 6px;
}

.unit-options {
  display: inline-flex;
  gap: 0.9rem;
  border: none;
  margin: 0;
  padding: 0;
}

.unit-options legend {
  font-weight: 700;
  margin-bottom: 0.25rem;
}

.size-result {
  font-weight: 700;
}

/* Footer */
.site-footer {
  background: #1a202c;
  color: #fff;
  padding: 2rem 1.5rem;
  margin-top: 3rem;
}

.footer-columns {
  display: flex;
  flex-wrap: wrap;
  gap: 3rem;
  max-width: 1100px;
  margin: 0 auto;
}

.site-footer h2 {
  font-size: 1rem;
  margin: 0 0 0.75rem;
}

.site-footer ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.5rem;
}

.site-footer a {
  color: #fff;
}

