  border-radius: 6px;
}

.unit-options {
  display: inline-flex;
  gap: 0.9rem;
  border: none;
  margin: 0;
  padding: 0;
}

.unit-options legend {
  font-weight: 700;
  margin-bottom: 0.25rem;
}

.size-result {
  font-weight: 700;
}

/* Footer */
.site-footer {
  background: #1a202c;
  color: #fff;
  padding: 2rem 1.5rem;
  margin-top: 3rem;
}

.footer-columns {
  display: flex;
  flex-wrap: wrap;
  gap: 3rem;
  max-width: 1100px;
  margin: 0 auto;
}

.site-footer h2 {
  font-size: 1rem;
  margin: 0 0 0.75rem;
}

.site-footer ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.5rem;
}

.site-footer a {
  color: #fff;
}

.newsletter {
  display: flex;
  gap: 0.5rem;
  align-items: center;
}

.newsletter input {
  font: inherit;
  padding: 0.45rem 0.7rem;
  border: 1px solid var(--border);
  border-radius: 6px;
}

